def linear(n):
    steps = 0
    for i in range(n):
        steps += 1
    return steps

def first(items):
    steps = 1          # одно действие
    return items[0], steps

def quadratic(n):
    steps = 0
    for i in range(n):
        for j in range(n):
            steps += 1
    return steps

def halving(n):
    steps = 0
    while n > 1:
        n = n // 2
        steps += 1
    return steps

def find(items, target):
    steps = 0
    for x in items:
        steps += 1
        if x == target:
            return steps
    return steps

def two_loops(n):
    steps = 0
    for i in range(n):
        steps += 1
    for i in range(n):
        steps += 1
    return steps

def total(items):
    s = 0               # одна переменная: память O(1)
    for x in items:
        s += x
    return s
